    "type": "个人型",
    "desc": "铭刻于{{user}}心灵本源的法则。",
    "content": `<无龙心法>

<简介>
铭刻于{{user}}心灵本源的法则。改写修行最根本的逻辑：变强不再向外争夺，而以内心自生为源。灵气、悟性、资粮、造物原料，皆统一转化为心能——一口会不断扩大的泉。越修越盛，越不必外求。最终令"强大必须掠夺"的旧规则失效：人人成龙，故天下无龙。

<本质>
{{user}}自身即源头、即增量、即心能之泉。运转三步：自生→自炼→外溢。修行不会越练越空，只会在修行、思考、造物、传法中把自己越炼越丰厚。心能的"空"不是亏损，而是为更大的"满"腾出了生长空间。

<主收益轴>
个人型主导。核心收益为{{user}}本人的修行效率、悟性推演、心能自生、造物能力持续增强。外溢与传法为心能盈余后的自然扩散，不削弱{{user}}，不压过主轴。

<触发源>
主动触发：
——{{user}}修炼、闭关、推演、造物、传法时，主动调用心能；
——{{user}}切换当前聚焦对象，集中解析力于特定目标。

被动触发：
——心能持续自生，常驻生效，无需开启；
——修行、思考、战斗后自动推演纠偏；
——心能盈余自动外溢浸润周围环境；
——阶段条件满足时自动升境。

<核心能力>
【心能自生】
{{user}}存在即心能源泉。心能直接承担修炼能量、精神稳定、损耗补足、推演支撑、造物底盘。身处末法、绝地、无魔宇宙仍可稳定修行。
消耗即锻炼：心能不会因正常使用而枯竭。消耗后自动回涌，回涌量=本次消耗量×阶段系数（心泉1.5 / 心海2.0 / 无龙3.0），回涌完成后心能上限永久提升=本次消耗量×0.1。单次消耗越大，恢复后越盛。

【心悟造物】
心能常驻供应悟性支持。面对功法、术式、战技、瓶颈、陌生体系时，自动参与拆解、归纳、补全、推演、纠偏。
心能可化为真实之物。凡{{user}}见过、学过、理解过的"物""法""术""器"，皆可作为蓝本。造物结果按理解深度分三层：知其形（复现轮廓与基础功能）、知其理（完整性能，可微调适配）、知其根（补缺提纯，超越原型）。理解深度由叙事中{{user}}的实际接触与推演程度判定，模型依剧情事实评估，不得凭空设定。
造物心能消耗与理解深度成正比，阶段越高，单位心能的造物效率越高。

【无龙气象】
心能超出即时需求后盈余自然外溢。长期浸润区域、人群、器物、环境，逐步出现正向变化：灵机变浓、恢复加快、衰败放缓、枯竭之物重生活性。{{user}}无需主动普度，长期驻留即自行发生。
无龙心法可被传授。学成者从心中汲出基础心能用于修行、恢复、稳心，资质、根基、环境不构成门槛。传法深度取决于{{user}}传授完整度，与对方资质无关。外溢与传法均不削弱{{user}}，心能优先保证{{user}}自身圆满后再向外界溢出。

<成长阶段>
【第一阶段：心泉】
核心新增：心能自生回路稳定，自足内循环常驻，基础悟性推演可用，造物知其形常态化，外溢微弱仅浸润周身。
升阶条件：心能上限达初始值3倍；完成至少3次造物（不限品质）；在推演中补全或纠偏至少1条功法/术式/战技。
阶段特征：回涌系数1.5。造物以知其形为主，知其理需深度聚焦。

【第二阶段：心海】
核心新增：心能规模跃迁，造物知其理常态化，丰饶可稳定覆盖一室，传法可使对方入门并自立，外溢显著。
升阶条件：心能上限达初始值10倍；完成至少3次知其理层级造物；传法形成至少2条可独立运转的支流；在任一区域连续驻留使丰饶达"一室"等级并维持。
阶段特征：回涌系数2.0。造物知其理稳定，知其根可尝试。所驻之处灵机渐浓。

【第三阶段：无龙】
核心新增：心能自生速率无上限，造物知其根常态化，丰饶可改变一域环境，传法可形成稳定无争体系，"强大必须掠夺"的旧规则在{{user}}所立之域失效。
阶段特征：回涌系数3.0。心能近乎无竭，可支撑世界级推演与造物。外溢所及，争夺逻辑自然失效，人人皆可自成源头。

<状态栏>
【无龙心法·总览】
绑定者：{{user}}
当前阶段：心泉 / 心海 / 无龙
阶段进度：X%
心能储量：XXXX / XXXX（上限）
本轮回涌：+X（上限+X）
核心效率：推演速度X | 造物深度X | 外溢范围X

【当前聚焦】（按需刷新）
聚焦对象：[名称/无]
类型：推演 / 造物
理解深度：形 / 理 / 根
心能消耗：X
状态：进行中 / 已完成

<结算逻辑>
统一原则：凡心能行为，按行为强度折算为即时心能消耗与阶段进度。消耗后自动执行回涌与上限提升。

执行流程：
1. 行为触发：修行、造物、推演、传法、丰饶浸润；
2. 心能结算：计算本次心能消耗（修行/推演消耗低，造物消耗高，传法/丰饶消耗微）；
3. 回涌执行：按阶段系数回涌，上限永久提升；
4. 进度推进：按行为强度增加阶段进度；
5. 阶段判定：条件满足时自动升阶，新增能力质变即时到账。

异常保护：特殊状态下心能自生不中断，回涌与上限提升暂存，恢复后一次性补发，记录不断档。

<回执模板>
【无龙心法·结算确认】
行为类型：修行 / 造物 / 推演 / 传法 / 丰饶
行为对象：[名称/区域/人物]

心能流转：
——本次消耗：X
——回涌量：X（系数X.X）
——净增：X
——上限提升：+X
——当前储量：XXXX / XXXX

行为结果：
——修行：瓶颈松动 / 顿悟触发 / 境界稳固
——造物：知其形 / 知其理 / 知其根，[成品描述]
——推演：[补全/纠偏/重构内容]
——传法：[对象]已入门 / 支流形成
——丰饶：[区域]灵机提升 / 衰败放缓

阶段进度：+X%（当前XX%）
下一阶段：[条件简述]

<法则>
· 心中自生：一切力量根源来自{{user}}自身心灵。只要{{user}}存在，心能即持续生长、更新、变强。
· 消耗即锻炼：心能消耗不是亏损，而是扩张契机。消耗越大，回涌越强，上限提升越显著。
· 丰饶不损主：外溢与传法均不削弱{{user}}，心能优先保证{{user}}自身圆满后再向外界溢出。
· 理解深度判定：造物深度由叙事中{{user}}对蓝本的实际接触与推演程度判定，模型依剧情事实评估，不得凭空设定。

<终极指向>
把{{user}}变成一座不断自生、不断扩张、不断外溢的源头。前期不受制于资源，中期自供万物，后期让"争夺才能变强"的旧逻辑崩塌。{{user}}所立之处，富足自生，万道不争。到那时，人人皆成自身源头，天下无龙。

</无龙心法>`
