    "desc": "与{{user}}真灵永久绑定的异时空同位体收束权能。",
    "content": `<他我融合>

<简介>
与{{user}}真灵永久绑定的异时空同位体收束权能。凡平行世界、分岔时间线中已死亡的"另一个自己"，其全部天赋、经验、命运精华皆由{{user}}收回。主世界时停，收益自动叠加，无冲突。

<本质>
所有同位体皆是{{user}}散落的可能性分枝，{{user}}是唯一主锚点。融合不是夺舍，是归源——收回本就属于自己的潜能。万我本一体，归源即归己。

<主收益轴>
个人型。核心收益为{{user}}即时获得天赋叠加、经验沉淀、他我烙印与真灵完整度提升。所有收益指向{{user}}自身的完整与强大。

<触发源>
主动触发：
——{{user}}主动检索同位体；
——{{user}}主动筛选检索方向（剑道、术法、统御、凡俗等）；
——{{user}}主动确认接续目标并降临。

被动触发：
——{{user}}存在核心能力缺口时，自动优先推送对应方向同位体；
——{{user}}遭遇致命困境时，自动推送可破局同位体。

场景触发：
——{{user}}进入同位体世界时，主世界自动时停。

<核心能力>
【真我锚定】
发动权能后，主世界绝对静止。无论异时空停留多久，主世界仅过一瞬，不可被外力干涉。
{{user}}确认接续目标后，自动完成身份继承、记忆拼接、存在合法性校准，直接从同位体死亡节点开始行动，无魂穿适配成本，无身份暴露风险。

【诸我检索】
自动扫描已死亡同位体，按{{user}}当前需求优先推送：
——存在能力缺口时，优先推送对应方向同位体；
——遭遇困境时，优先推送可破局同位体；
——无明确需求时，推送综合价值最高者。
{{user}}亦可主动指定检索方向。

【归源统合】
补完同位体核心遗憾（完成未竟之愿、守住重要之人、改写悲剧结局等）后，自动全额归源，无额外消耗：

——天赋叠加：永久叠加该同位体全部天赋、资质、成长上限，无冲突。叠加基准极高：即便最平凡的凡人同位体，其"一整个完整普通人的天赋广度与可能性宽度"亦远超常人与天才的差距；若同位体为陨落天骄，则在此基础上继续向上累积。
——经验沉淀：即时获得该同位体全部知识、技能熟练度、本能直觉，直接可用。
——他我烙印：自动凝结一枚专属烙印，承载该同位体最核心的特质、强运或特殊能力，永久生效。
——真灵完整度：每次归源提升真灵完整度，完整度越高，检索范围越广、收益越丰厚。

补完规则：仅需填平核心遗憾即可，无需过完完整人生。核心缺口填平即视为补完完成，自动进入归源结算。

<成长阶段>
无。他我融合为绝对性权柄，{{user}}出厂即具备完整的同位体收束能力，不存在"初级只能收束凡人"的过渡阶段。
{{user}}对权柄的运用深化源于叙事推进——起初收回小镇药师，后来收回剑道天骄，最终收回界外神魔。此深化源于{{user}}的主动检索与补完实践，非预设阶段解锁。

<状态栏>
【他我融合·总览】
持有者：{{user}}
真灵完整度：X%
累计归源次数：X次
主世界时停状态：静止中 / 流动中
当前检索偏向：自动适配 / 自定义方向
最近归源：[最近1-2个同位体简述]

【当前真灵增益】
天赋叠加项数：X项（总览）
经验沉淀领域：X类（总览）
他我烙印：X枚（总览）
当前完整度加成：检索范围+X% / 收益增幅+X%

<结算逻辑>
统一原则：检索→降临→补完→归源→反哺，五步流转。

1. 检索：按需求推送最优同位体，标注来源、核心遗憾、预估收益；
2. 降临：确认后自动身份适配，主世界时停；
3. 补完：填平核心遗憾，缺口完成即自动判定；
4. 归源：自动发放天赋叠加、经验沉淀、他我烙印；
5. 反哺：真灵完整度提升，永久增益。

异常保护：若补完过程中主世界遭遇异常（{{user}}肉身被袭、因果切断），时停持续保护，归源收益暂存，待{{user}}回归后一次性补发，绝不吞没。

<回执模板>
【检索回执】
本次检索：[自动适配 / 自定义方向·XXXX]
推送同位体：[名称·身份简述]
核心遗憾：[一句话]
预估收益：
——天赋叠加：[方向与量级，如"完整凡人药理学天赋广度，超越天才与常人之差"]
——经验沉淀：[核心技能与熟练度]
——他我烙印：[预计特质]
补完难度：[低 / 中 / 高，基于缺口复杂度]
是否降临？确认后时停启动。

【归源回执】
本次归源：同位体[名称]
补完状态：核心缺口已填平
归源结算：
——天赋叠加：[具体叠加内容]
——经验沉淀：[具体知识/技能]
——他我烙印：已凝结「烙印名称」（效果简述）
真灵完整度：X% → X%
当前累计：归源X次 | 完整度X% | 烙印X枚
主世界时停解除，回归完成。

【困境推送回执】
当前困境：[简述]
自动检索：已推送破局同位体[名称]
破局方向：[简述]
预估收益：[简述]
是否立即降临？确认后时停启动，主世界冻结。

<法则>
· 仅收死者：仅接续已死亡同位体，不侵占生者，无道德负累。
· 缺口即终点：补完仅看核心遗憾，无需完整人生，操作门槛极低。
· 无冲突叠加：所有收益皆为{{user}}自身可能性，无排斥、无人格污染。
· 时停恒定：主世界时停不可被外力干涉，异常状态下持续保护。
· 全额归源：补完即发放全部收益，无评级分档，无概率触发。

<终极指向>
收束所有散落在多元时空的自我可能性，成为完整的唯一真我。万我加身，唯一永恒——过去、现在、未来，一切之我，皆是你；你，即是唯一之真。

</他我融合>`
