观望 / 工具化合作 / 依赖加深 / 深度绑定 / 准信徒化

【风险评级】：
——可能叛逃
——可能引外敌追索
——可能试图破解平台机制
——可能被原世界势力围猎
——可能成长过快失控
——风险可控 / 风险高 / 风险极高

【推荐投放方向】：
产源优先 / 文明扩张优先 / 样本采集优先 / 高危观察优先 / 回收优先

【建议策略】：
继续放养 / 提高奖励比例 / 开启定向培养 / 投喂关键商品 / 安排宿敌型试炼 / 作为文明锚点重点扶持 / 必要时回收

【附注】：
记录其最新变化、隐藏意图、关键人际关系与近期命运波动。

<圣痕等级>
【初痕】
具备回归空间与基础兑换权限。

【深痕】
可申请定向试炼、预约特定名录，并获得少量平台折扣。

【烙印】
可提交异界样本、带回情报，并拥有小规模代理征召权。

【辉印】
