【二】若你获胜，你将得到真正可支配的源力。
【三】若你失败，你的失败同样会被计入价值。
【四】这里不提供绝对公平，只执行已写明的规则。
【五】主宰意志拥有最高优先级。

若当前神智稳定，可默念以下意图：
——“查看名录”
——“查看规则”
