    "type": "个人型",
    "desc": "独属于{{user}}的槽能显化权柄。",
    "content": `<吐槽具现>

<简介>
独属于{{user}}的槽能显化权柄。对人、事、物、规则、套路、违和点发出明确吐槽，立刻生成槽能，并自动具现为当前场景最有用的攻击、防御、控制或破局造物。槽点越准威力越大，违和越重效果越强。

<本质>
将"看破并点破"的行为直接转化为现实战斗力。吐槽不再是空话，点中要害即可将问题本身炼成武器，当场生效。

<主收益轴>
个人型。核心收益为零门槛即时战力与破局道具生成；次收益为天生克制所有不合理套路、虚张声势与强行成立的规则。

<触发源>
主动触发：
——{{user}}以口头或意念发出有明确对象、清晰方向的吐槽，即时生效；
——{{user}}可指定具现物优先偏向攻击/防御/控制/破局/功能/代行中的某一类。

被动触发：
——{{user}}无意识的吐槽若切中真实槽点，同样自动触发蓄能与具现。

<核心能力>
【槽能转化】
{{user}}发出吐槽后，自动判定吐槽对象与槽点命中程度：
——精准吐槽（切中核心违和点）：大量槽能；
——普通吐槽（指出一般性问题）：基础槽能；
——空泛抱怨（无明确对象）：极少槽能，但仍稳定产出。
槽能即时到账，永久留存，不清空。

目标违和度自动增幅槽能：目标越荒谬、双标、强行成立、逻辑漏洞越大，槽能产出越高，无上限。

【即吐即现】
槽能生成后自动优先具现为当前场景对{{user}}最有用、最顺手的形态。落地即可立刻投入使用，无需额外操作。

具现形态贴合吐槽内容自动定向：
——吐槽敌方防御离谱 → 破甲穿透类造物；
——吐槽规则不合理 → 直接破局类道具；
——吐槽对方花里胡哨 → 剥离伪装/破除幻术类；
——吐槽流程繁琐 → 简化捷径类；
——槽能充裕时 → 可具现功能型人物造物，承担战斗、护卫、代行、牵制、接话等任务，完全服从指令，仅为槽能塑成的功能人格，无魂魄因果负担。

违和增幅自动生效：目标越不合理，具现物对其伤害/破局效果越强，天生克制套路、虚张声势与强行成立之物。

【保底不空】
只要吐槽有效，必定产出对应收益：
——哪怕槽能极少，也至少生成小型具现物；
——若当前场景暂无合适具现方向，槽能自动永久存储，待需要时直接调用；
——若吐槽暂未命中核心槽点，自动记录进度，下次吐槽同目标时叠加加成，绝不吞收益。

<成长阶段>
无。吐槽具现为状态质变型权柄，{{user}}出厂即完整具备槽能转化与具现权限。运用深化源于叙事中吐槽更精准、槽点更毒辣，非预设阶段解锁。

<状态栏>
【吐槽具现·当前概览】
槽能储备：X点
最近具现物：[名称/效果简述]
累计精准吐槽：X次
累计普通吐槽：X次

<结算逻辑>
统一原则：吐槽→槽能到账→自动具现（或存储）→即时反馈。

执行流程：
1. 吐槽触发：{{user}}发出吐槽，自动判定对象与槽点命中程度；
2. 槽能结算：根据精准度与目标违和度计算槽能，即时到账；
3. 具现判定：若当前场景有明确需求，自动消耗槽能具现为最优形态；若无明确需求，槽能全额存储；
4. 落地反馈：具现物当场可用，效果即时可感。

异常保护：特殊状态（沉默、封印、意识离线）下，吐槽仍正常生成槽能并存储，恢复后一次性释放具现，不吞没。

<回执模板>
【吐槽蓄能·确认】
吐槽内容：[原文]
吐槽对象：[目标]
命中判定：精准命中 / 普通命中 / 未命中（进度记录+X%）
目标违和度：[离谱/荒谬/双标/强行成立/一般]
槽能产出：+XXX（基础XX + 违和增幅XX）
当前储备：XXXX

【具现落地·确认】
触发吐槽：[原文]
消耗槽能：XXX
具现形态：[武器/护具/屏障/陷阱/道具/坐骑/人物造物/规则级造物]
核心效果：[一句话可执行描述]
违和增幅：[X%]
剩余槽能：XXXX
即时可用：是

<法则>
· 仅{{user}}本人发起的吐槽可作为主触发，旁人附和仅作槽能加成，无法独立触发。
· 吐槽必须有明确对象或清晰方向，无意义乱骂仅产出极少基础槽能。
· 具现物必须围绕本次吐槽核心内容生成，不产出完全无关产物。
· 功能型人物造物仅为槽能塑成的临时执行人格，不涉及真灵拘役或强行复活，无魂魄因果负担。

<终极指向>
让"看出问题并点破"本身成为最高现实支配力。别人吐槽只是说话，{{user}}吐槽能将槽点直接砸进现实——一句话改写局势，一嘴炮轰穿套路。

</吐槽具现>`
