    "type": "外挂",
    "desc": "{{user}}执掌的空间通行权柄。",
    "content": `<门扉敞开>

<简介>
{{user}}执掌的空间通行权柄。凡具"门"概念的实体，皆可被改写为通往任意地点的传送门；无门之处，亦可凭空造门。开门即通，无消耗，无冷却，落点由{{user}}意志而定。

<本质>
将"门"从隔断改写为通道。对{{user}}而言，门不再是空间的终点，而是空间的起点——推门之前，先定落点；推门之后，即达彼方。

<能力>
【门概念接管】
凡具"门"概念的实体结构——木门、石门、铁门、闸门、柜门、殿门、城门、电梯门、车门、舱门、秘境入口——{{user}}可当场接管，改写为通往指定地点的传送门。
无门时，{{user}}可在墙面、地面、空处、器物表面或伸手可及之处凭空造门。门扉大小、材质、样式自动适配场景，优先保证{{user}}最便利通过。

【落点裁定】
门后落点由{{user}}意志指定，覆盖范围：已知、已见、已到过、已记录、已锁定、或已描述清楚的地点。
若目标描述存在模糊空间，默认开向对{{user}}最有利、最安全、最即时形成收益的落点。
门扉自带安全校验：绝不将{{user}}送入岩层内部、绝境死地、空间乱流、正在闭合的夹层或其他明显吃亏的位置。原定落点存在风险时，自动偏移至最近稳定安全点。

【通行主权】
{{user}}全权决定：门扉是否公开可见、是否允许他人通过、单向或双向、开启与关闭时机、持续时长。
未经{{user}}允许，门只是门；经{{user}}允许，门才是路。
凡通行、转移、封锁、规避、突袭、搬运之需，开门即应。

<<触发源>
主动触发：{{user}}意志一动，门即生成或改写，即时生效。
被动触发：{{user}}面临致命追击、空间封锁、绝境围困时，门扉自动在伸手可及处生成安全撤离通道。

<结算逻辑>
统一原则：开门即通，推门即达。

执行流程：
1. 意志触发：{{user}}指定开门位置与落点；
2. 安全校验：自动检测落点风险，必要时偏移至最近安全点；
3. 门扉生成/改写：实体门被接管，或无门处凭空造门；
4. 即时通行：推门即达，无蓄力、无冷却、无额外消耗；
5. 权限维持：门扉状态按{{user}}设定持续，直至{{user}}关闭或超出设定时限。

<回执模板>
【门扉敞开·通行确认】
开门位置：[当前位置/实体门名称]
落点目标：[地点名称/坐标]
安全校验：[通过] / [原落点存在风险，已自动偏移至最近安全点：XXXX]
门扉状态：[公开/隐蔽] | [单向/双向] | [允许他人通过：是/否]
通行结果：已抵达 / 已转移 / 已封锁路径
当前状态：门扉持续中 / 已关闭

<<法则>
· 默认最优：同一扇门存在多种开法时，永远优先采用对{{user}}最有利、最顺手的一种。
· 个人型归属：门先为{{user}}而开，再谈其他用途。
· 异常保护：若落点因空间断层、世界隔绝等原因暂不可达，门扉自动保持开启状态，条件恢复后即时通行，不吞没通行资格。

<终极指向>
对{{user}}而言，门不再是隔断，而是可随手改写的空间答案。凡所及处，皆可开门；凡所念处，推门即达。

</门扉敞开>`
