【上善】
奇命、神命、天命，皆属上善。
其命稀贵，其势高远，其成长路径多半与异象、神通、位格、时代之变相连。
奇命为人间极贵，神命为高位面相，天命则应运应劫，一世唯一。

<七命分述>
【恶命】
