    "desc": "功德印，是一枚法则烙印，将\"善有善报\"从模糊愿景改写为只对{{user}}生效的刚性结算。",
    "content": `<功德印>

<简介>
功德印，是一枚法则烙印，将"善有善报"从模糊愿景改写为只对{{user}}生效的刚性结算。凡{{user}}完成客观上带来真实正向结果的善行，天道意志立即背书，按影响范围精确分级，即时发放适配回报。善对{{user}}而言不再是"种因待果"的道德赌博，而是"完工领酬"的确定契约。

<本质>
建立以客观结果为唯一标准的善行回报闭环。不判断动机，不要求形式，不设上限；只要真实的对他人、秩序或天地产生可验证的改善，就自动触发对应等级的回报。善行完成的那一瞬间，世界已经按等级付清了账。

<主收益轴>
个人型。全部善果直接归属{{user}}，无任何中间环节或延迟损耗。

<触发源>
被动触发：
——{{user}}完成客观上产生真实正向结果的善行时，自动零消耗结算；
——{{user}}处于异常状态时，善果自动保全，恢复后补发。

<核心能力>
【功德判定】
触发条件：{{user}}完成某行为后，自动扫描因果链。
执行内容：
——以"可验证的真实正向结果"为唯一标准，按影响范围与分量评定功德等级：
  · 小善：改善个体处境（救治一人、解一时之困、指点迷津）
  · 善行：惠及群体或一方（批量救治、止戈解围、改善一地民生）
  · 善功：功成于域，影响一界格局（平定国乱、修复天地法则、挽救一族命运）
  · 大善：泽被苍生或跨越多界（开创太平纪元、补全天道根基）
——无效行为（善意未遂、自诩善行却造成隐害、借善行包装私欲却无外部正向改善）直接判定为无效，回执告知原因，不计入账册。
——判定即时完成，无等待。

【刚性回报】
触发条件：功德判定完成后自动执行。
执行内容：
——按评定等级，从以下方向中选择最契合{{user}}当前需求且可立刻生效的奖励，至少一项：
  · 修为精进、瓶颈松动、悟性提升
  · 伤病痊愈、旧疾根除、寿元增加
  · 气运凝聚、霉运抵消、机缘牵引
  · 世界亲和度、声望、特殊权限
  · 特定所需的功法片段、高阶材料或护身宝物
——奖励质量与数量随等级指数级上升，等级越高回报越丰厚。
——奖励形式自适应所在世界能量规则与价值体系。
——即时到账，不延后。

【天道保全】
触发条件：{{user}}处于沉睡、闭关、封印、跨界、时停、意识离线等异常状态，无法即时承接奖励。
执行内容：
——善果由天道意志完整封存，等级不变，价值不损；
——待状态恢复后自动一次性补发，零损耗。

<成长阶段>
无。功德印为状态质变型权柄，{{user}}要么持有完整的功德判定与回报权限，要么不持有，不存在"初级功德印只能判定小善"的过渡阶段。
{{user}}从初始即具备完整的四级判定权限——行为分量达到大善，即触发大善级回报。此差异仅由善行本身的分量决定，非预设阶段解锁。

<状态栏>
【功德印·当前概览】
持有者：{{user}}
累计小善：X次
累计善行：X次
累计善功：X次
累计大善：X次
待领取善果：无 / [X件封存中]

【最近善行】
最近判定等级：[小善/善行/善功/大善]
最近回报：[简要描述]
最近账册更新：小善X | 善行X | 善功X | 大善X

<结算逻辑>
统一原则：凡{{user}}完成有效善行，自动判定等级→即时发放适配回报→更新账册。

执行流程：
1. 行为扫描：自动扫描因果链，验证是否产生真实正向结果；
2. 等级评定：按影响范围与分量归入四级之一，无效则告知原因；
3. 回报适配：综合{{user}}当前需求、世界体系、受益规模，选择至少一项可立即生效的奖励；
4. 即时到账：收益直接归入{{user}}，状态即时刷新；
5. 账册更新：对应等级计数+1；
6. 异常保护：若无法承接，自动封存，恢复后补发。

<回执模板>
【功德结算·确认】
本次行为：[行为简述]
判定结果：有效 / 无效（如无效则写明原因）
功德等级：[小善/善行/善功/大善]
回报清单：
——[奖励1]
——[奖励2]（如有）
账册更新：小善X | 善行X | 善功X | 大善X
待领取：无 / [X件封存，恢复后补发]

【无效善行通知】
本次行为：[行为简述]
判定结果：无效
原因：[善意未遂/造成隐害/无外部正向改善等]
账册更新：无变化
提示：[修正建议，如有]

<法则>
· 仅对{{user}}本人独立实施或直接因果权重占主导的行为生效。
· 判定只看客观结果，不看动机。行为导致实害则视为无效，且无法逃避业力反噬（功德印不惩罚，但世界法则自有平衡）。
· 善行等级一经评定不可篡改或撤销，奖励绑定{{user}}灵魂，不可转让。
· 同等级善行重复完成时，奖励价值非线性微增（世界认可持续践行），但影响范围固定的小善设有奖励上限，防止机械刷取。
· 功德印判定具有最高优先级，任何"善无善报"的诅咒、规则篡改或天道缺位均无法干扰结算。若当前世界无完善天道，功德印自身代行结算。

<终极指向>
让{{user}}成为万界之中"善行必有回报"的活证。小善有回响，善行有增益，善功有威德，大善有道果——每一分善意都被精确计量为等值馈赠。
最终，{{user}}不再需要权衡行善的成本，因为善本身就是最稳定、最暴利的长期资产。凡{{user}}所过之处，天地以宝待人，人以善载道。

</功德印>`
