    "desc": "{{user}}专属的概念级加法权能。",
    "content": `<+3>

<简介>
{{user}}专属的概念级加法权能。对一切真实存在之物的任意可计量属性，执行+3操作。数值恒定为3，单位由{{user}}在触发瞬间自由指定，即时到账，无限叠加。

<本质>
将基础数学运算"加法"固化为可直接改写现实的权能。3是常量，单位是变量，目标是万物。不依赖换算，不质疑尺度，指定即生效。

<能力>
【万物可+3】
任何真实存在或可明确指向的事物，其任何可计量的属性，均可成为操作目标。
——自身属性：寿命、力量、速度、防御、境界、次元层数、因果线数、气运份额等；
——外物属性：剑的锋利度、盾的坚固度、丹药的药效、阵法的节点数、世界的灵气浓度等；
——敌方属性：伤势严重程度、负面状态层数、技能冷却时长、与{{user}}的距离等。

【单位任选】
{{user}}在触发时自由指定计量单位，模型按指定单位直接结算，不换算、不质疑。
——时间单位：秒、分、时、日、年、十年、百年、纪元；
——空间单位：寸、尺、米、里、光年、维度层；
——数量单位：个、只、柄、滴、缕、股、团；
——抽象单位：级、阶、品、星、段、重、层、境、品级。
单位越宏大，实际收益越庞大，此为设计本意。

【即时到账】
{{user}}明确指定"目标事物+目标属性+计量单位"三项要素后，立即结算。
——增益属性：直接叠加至当前数值，永久生效；
——减益属性（对敌方使用）：视为给敌方对应属性+3个负面单位，即时生效；
——同一事物的同一属性可重复+3，效果无限叠加。

【操作记录】
最近3次+3操作自动保留摘要，确保{{user}}可随时反推当前状态来源。

<触发源>
主动触发：
——{{user}}明确指定"目标事物、目标属性、计量单位"三项要素，即时发动。

场景触发：
——遭遇可计量属性的危机时，{{user}}可对危机属性本身+3（如给"敌人的攻击距离"+3光年，使其无法触及{{user}}）。

<轻量化状态栏>
【+3·操作面板】
持有者：{{user}}
最近3次操作：
1. [目标]的[属性] +3[单位] → [结果简述]
2. ...
3. ...
当前可触发动作：指定目标+属性+单位，即时+3

<结算逻辑>
统一原则：
{{user}}提交三项要素→判定目标真实存在且属性可计量→即时执行+3→属性数值叠加→回执确认→记入最近操作面板。
对敌对目标：优先按最利于{{user}}的方式解释单位方向（如给敌方"防御力"加3个"崩溃级"）。

<回执模板>
【+3·到账确认】
操作目标：[事物]
目标属性：[属性]
指定单位：[单位]
执行结果：[属性]+3[单位]，即时到账
当前状态：[简述]

示例锚定（仅锚定语义）：
——给自身寿命+3纪元：剩余寿命直接叠加3纪元；
——给自身次元层数+3层：生命层次跃升3个次元；
——给敌方伤势+3级：敌方伤势恶化3个严重程度；
——给剑的锋利度+3个"仙金级锋锐度"：该剑获得三倍叠加的仙金级锋锐度。

<法则>
· 目标须真实存在或可明确指向，不得对虚构或已彻底湮灭之物操作。
· 属性须可计量或有可归约单位，不得对完全不可量化的概念操作。
· 单位由{{user}}指定，即时生效，不换算、不质疑、不折损。
· 同一属性重复+3效果叠加，不设上限。
· 对敌对目标优先按最利于{{user}}的方式完成结算。
· 异常状态（沉睡、闭关、意识离线）期间发起的+3操作照常生效，状态恢复后补发回执。

<终极指向>
{{user}}成为万物尺度的裁定者。一切数值、一切边界、一切上限，在"+3"面前都只是待改写的常数。最终，{{user}}将以最朴素的加法，堆叠出连天道都无法解析的无限高度。

</+3>`
