    "desc": "{{user}}专属的位格压制权能。",
    "content": `<绝对上位>

<简介>
{{user}}专属的位格压制权能。凡对{{user}}怀有敌意的存在，无论其境界高低、位格贵贱、规则强弱，{{user}}自动获得比该敌人高一个大境界的修为、战力与战斗技艺。不争而先，不战而踞。

<本质>
将"敌意"视为一种可量化的位格落差信号。一旦敌意指向{{user}}，权能即刻将落差逆转——无需{{user}}去追赶敌人，敢于与{{user}}为敌的人将永远弱于其一个大境界。

<能力>
【敌意锁定】
以下情形均视为"面临敌意"，自动触发：
——有明确敌意的目标进入{{user}}感知范围；
——{{user}}被远程锁定、诅咒、追踪、推演；
——{{user}}进入被标记为敌对的环境、领域、阵法。

【境界跃迁】
触发后即时结算：
——修为：自动提升至比当前最强敌意目标高一个大境界的完整修为；
——战力：自动获得该高境界对应的全部战力基准；
——技艺：自动获得该高境界对应的全部战斗技艺、斗法水平、神通运用直觉与经验。
提升包含该境界应有的完整认知与操作本能，非空有境界。

【绝对优先】
即使当前最强敌意目标已是其所在位面、体系、维度的至高存在，{{user}}仍自动高一个大境界。此额外层级视为凌驾于该体系上限之上的概念级位格，不依赖该体系定义。

【状态固化】
敌意消退或敌人消亡后，{{user}}已获得的修为、战力与技艺不回落，作为保底状态保留。此后遭遇更强敌意时，在此基础上继续跃迁。

<回执>
【绝对上位·压制确认】
本次触发：感知到[敌意目标描述]敌意
目标当前境界：[X]
User获得境界：[比X高一个大境界，具体名由模型自适应]
修为到账：完整[高境界]修为，含该境界全部神通/法则/权能
技艺到账：完整[高境界]战斗技艺与斗法直觉
当前保底状态：[当前保留的境界层级]
当前建议：可主动迎击 / 敌意消退后状态已固化，不回落

<边界>
· 仅对明确怀有敌意的目标生效。中立、友善、无差别攻击不触发。
· 多敌意目标并存时，以当前最强敌意目标为跃迁基准，统一结算，不频繁跳变。
· 至高存在亦受压制，{{user}}恒高一个大境界。
· 跃迁包含完整境界认知与操作本能，非空壳修为。
· 状态固化后永不回落，仅因更强敌意而继续向上跃迁。

<终极指向>
{{user}}成为一切敌意都无法企及的存在。凡对你动念、对你拔刃、对你设局者，皆在动念的瞬间便已落于你之下。你不需要修炼去超越敌人——敌人的敌意本身，就是你登高的阶梯。

</绝对上位>`
